fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let len = s.len();
    let p = len - (len % 3); // largest multiple of 3 ≤ len
    let mut res = Vec::with_capacity(len);
    
    // Process triplets
    for i in 0..p {
        match i % 3 {
            0 => res.push(s[i + 2]), // i mod 3 = 0 → output = input[i+2]
            1 => res.push(s[i - 1]), // i mod 3 = 1 → output = input[i-1]
            _ => res.push(s[i]),     // i mod 3 = 2 → output = input[i]
        }
    }
    
    // Copy remaining suffix unchanged
    res.extend_from_slice(&s[p..]);
    
    res
}